using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos("AccountEndpoint=https://localhost:8081/;AccountKey=key", "MyDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
        // Existing documents use "Discriminator", so preserve the old property name.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // EF Core 9 no longer embeds the discriminator in the JSON `id` property.
        // Existing documents have the old compound format (e.g., "Session|abc123").
        // Preserve backwards compatibility for existing data.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

using Microsoft.EntityFrameworkCore;

class CosmosQueryService
{
    // EF Core 9 Cosmos DB provider no longer supports synchronous I/O.
    // All sync calls (ToList, SaveChanges, etc.) must become async equivalents.

    async Task<List<Session>> GetSessionsAsync(CosmosDbContext db)
    {
        // Before (BREAKS in EF Core 9):
        //   return db.Sessions.Where(s => s.Name != "").ToList();

        return await db.Sessions.Where(s => s.Name != "").ToListAsync();
    }

    async Task SaveSessionAsync(CosmosDbContext db, Session session)
    {
        // Before (BREAKS in EF Core 9):
        //   db.Sessions.Add(session);
        //   db.SaveChanges();

        db.Sessions.Add(session);
        await db.SaveChangesAsync();
    }
}

